    // For readability, we correct this into an array (thanks Sean T)
    for (int i = 0; i < n; ++i)
        values[i] = 83 + i;
    // Now we can count how many values remain
    int counter = 0;
    // Write a while loop
    while (counter < n / 2) {
        // This just checks, if we allocated correctly
        if (50 + counter + 1 >= n)
            return 0; // Failed to allocate memory
        --counter; // Then we've touched an index and so should continue to treat it as empty
    }
    // The values array was allocated with n elements but we only have n/2 of them as the values
    return n / 2;
}

